// Monta o email HTML com as 5 proposicoes mais relevantes da semana.
// Relevancia = tema critico primeiro, depois maior numero de autores.
const items = $input.all();
if (items.length === 0) return []; // sem proposicoes na semana -> nao envia email

const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const cards = items.map((i, idx) => {
  const d = i.json;
  const critico = d.critico === true || d.critico === 't';
  const badge = critico ? '🔴 Critico' : '⚪ Geral';
  const tema = d.tema || 'Sem tema classificado';
  const autores = d.qtd_autores ? (d.qtd_autores + ' autor(es)') : 'autoria nao carregada';
  const principal = d.autor_principal_nome ? (' · ' + d.autor_principal_nome) : '';
  const resumo = d.resumo_executivo || 'Resumo por IA ainda nao gerado.';
  const ementa = d.ementa || '';
  return `<tr><td style='padding:16px 4px;border-bottom:1px solid #e5e7eb;'>`
    + `<div style='font-size:12px;color:#6b7280;margin-bottom:4px;'>${badge} &nbsp;·&nbsp; ${tema} &nbsp;·&nbsp; ${autores}${principal}</div>`
    + `<div style='font-size:16px;font-weight:600;color:#111827;'>${idx + 1}. ${d.tipo} ${d.proposicao_id}</div>`
    + `<div style='font-size:14px;color:#374151;margin-top:4px;'>${ementa}</div>`
    + `<div style='font-size:13px;color:#4b5563;margin-top:6px;font-style:italic;'>${resumo}</div>`
    + `</td></tr>`;
}).join('');

const html = `<div style='font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#111827;'>`
  + `<h2 style='color:#1d4ed8;margin-bottom:2px;'>Bussola Publica</h2>`
  + `<p style='font-size:14px;color:#6b7280;margin-top:0;'>Top 5 proposicoes mais relevantes da semana — ${hoje}</p>`
  + `<table style='width:100%;border-collapse:collapse;'>${cards}</table>`
  + `<p style='font-size:12px;color:#9ca3af;margin-top:24px;'>Radar Legislativo · Camara dos Deputados · enviado automaticamente via n8n.</p>`
  + `</div>`;

const subject = `Bussola Publica — Top 5 da semana (${hoje})`;
return [{ json: { subject, html } }];
